function check(input, actual, expected) {
  const [n, , group, beforeItems] = input;
  if (!Array.isArray(actual)) return false;
  // The reference (or LeetCode) found no arrangement, so none exists.
  if (Array.isArray(expected) && expected.length === 0) return actual.length === 0;
  if (actual.length !== n) return false;
  const position = new Array(n).fill(-1);
  for (let index = 0; index < n; index++) {
    const item = actual[index];
    if (!Number.isInteger(item) || item < 0 || item >= n || position[item] !== -1) return false;
    position[item] = index;
  }
  for (let item = 0; item < n; item++) {
    for (const before of beforeItems[item]) if (position[before] > position[item]) return false;
  }
  const closed = new Set();
  for (let index = 0; index < n; index++) {
    const id = group[actual[index]];
    if (id === -1) continue;
    if (closed.has(id)) return false;
    if (index + 1 === n || group[actual[index + 1]] !== id) closed.add(id);
  }
  return true;
}

