function validate([n, m, group, beforeItems]) {
  if (!Number.isInteger(n) || n < 1 || n > 30000) return 'n is between 1 and 30000.';
  if (!Number.isInteger(m) || m < 1 || m > n) return 'm is between 1 and n.';
  if (group.length !== n || beforeItems.length !== n) return 'group and beforeItems each need n entries.';
  if (group.some(id => !Number.isInteger(id) || id < -1 || id >= m)) return 'Each group[i] is -1 or a group number below m.';
  for (let item = 0; item < n; item++) {
    const seen = new Set();
    for (const before of beforeItems[item]) {
      if (!Number.isInteger(before) || before < 0 || before >= n) return 'beforeItems holds item numbers from 0 to n - 1.';
      if (before === item) return 'An item cannot have to come before itself.';
      if (seen.has(before)) return 'A beforeItems list has no repeated items.';
      seen.add(before);
    }
  }
  return null;
}

