function sortItems(n, m, group, beforeItems) {
  const groupOf = [...group];
  let groupCount = m;
  for (let item = 0; item < n; item++) {
    if (groupOf[item] === -1) {
      groupOf[item] = groupCount++;
    }
  }
  const itemNext = Array.from({ length: n }, () => []);
  const itemIndegree = new Array(n).fill(0);
  const groupNext = Array.from({ length: groupCount }, () => []);
  const groupIndegree = new Array(groupCount).fill(0);
  for (let item = 0; item < n; item++) {
    for (const before of beforeItems[item]) {
      itemNext[before].push(item);
      itemIndegree[item]++;
      if (groupOf[before] !== groupOf[item]) {
        groupNext[groupOf[before]].push(groupOf[item]);
        groupIndegree[groupOf[item]]++;
      }
    }
  }
  const itemOrder = topologicalOrder(itemNext, itemIndegree);
  const groupOrder = topologicalOrder(groupNext, groupIndegree);
  if (itemOrder.length < n || groupOrder.length < groupCount) {
    return [];
  }
  const members = Array.from({ length: groupCount }, () => []);
  for (const item of itemOrder) {
    members[groupOf[item]].push(item);
  }
  const result = [];
  for (const id of groupOrder) {
    for (const item of members[id]) {
      result.push(item);
    }
  }
  return result;

  function topologicalOrder(next, indegree) {
    const order = [];
    for (let node = 0; node < next.length; node++) {
      if (indegree[node] === 0) {
        order.push(node);
      }
    }
    for (let head = 0; head < order.length; head++) {
      for (const target of next[order[head]]) {
        indegree[target]--;
        if (indegree[target] === 0) {
          order.push(target);
        }
      }
    }
    return order;
  }
}

