function sortItems(n, m, group, beforeItems) {
  // Try every arrangement in lexicographic order and return the first that follows both rules.
  const order = Array.from({ length: n }, (_, i) => i);
  const valid = () => {
    const position = new Array(n);
    order.forEach((item, index) => { position[item] = index; });
    for (let item = 0; item < n; item++) for (const before of beforeItems[item]) if (position[before] > position[item]) return false;
    const finished = new Set();
    for (let index = 0; index < n; index++) {
      const id = group[order[index]];
      if (id === -1) continue;
      if (finished.has(id)) return false;
      if (index + 1 === n || group[order[index + 1]] !== id) finished.add(id);
    }
    return true;
  };
  for (;;) {
    if (valid()) return order.slice();
    let i = n - 2;
    while (i >= 0 && order[i] > order[i + 1]) i--;
    if (i < 0) return [];
    let j = n - 1;
    while (order[j] < order[i]) j--;
    [order[i], order[j]] = [order[j], order[i]];
    const tail = order.slice(i + 1).reverse();
    for (let k = 0; k < tail.length; k++) order[i + 1 + k] = tail[k];
  }
}

