function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 7);
  const m = large ? 1 + Math.floor(rand() * 300) : 1 + Math.floor(rand() * n);
  const group = Array.from({ length: n }, () => (rand() < 0.3 ? -1 : Math.floor(rand() * m)));
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // Lay the items out in a hidden order where every group is one block, then only add rules that agree with it.
  const blocks = new Map();
  for (let item = 0; item < n; item++) {
    const key = group[item] === -1 ? `free${item}` : `group${group[item]}`;
    if (!blocks.has(key)) blocks.set(key, []);
    blocks.get(key).push(item);
  }
  const hidden = shuffle([...blocks.values()]).flatMap(block => shuffle(block));
  const beforeItems = Array.from({ length: n }, () => []);
  const listed = Array.from({ length: n }, () => new Set());
  const addRule = (before, item) => {
    if (before === item || listed[item].has(before)) return;
    listed[item].add(before);
    beforeItems[item].push(before);
  };
  for (let index = 1; index < n; index++) {
    const count = Math.floor(rand() * (large ? 5 : 3));
    for (let k = 0; k < count; k++) addRule(hidden[Math.floor(rand() * index)], hidden[index]);
  }
  // Some inputs get a few unrestricted rules, which often make an arrangement impossible.
  if (rand() < (large ? 0.3 : 0.4)) {
    const extra = 1 + Math.floor(rand() * 2);
    for (let k = 0; k < extra; k++) addRule(Math.floor(rand() * n), Math.floor(rand() * n));
  }
  return [n, m, group, beforeItems];
}
